// Handle node enable/disable before the legacy renderer wrapper's handler.
document.addEventListener('click',event=>{
  const button=event.target.closest('[data-node-toggle]');
  if(!button)return;
  event.preventDefault();
  event.stopImmediatePropagation();
  const index=Number(button.dataset.nodeToggle),node=state.recipe.nodes?.[index];
  if(!node)return;
  node.enabled=node.enabled===false;
  if(node.type==='filter')state.recipe.filter=node.enabled?node.name:'none';
  if(node.type==='local_correction')state.recipe.local_correction=node.enabled?node.name:'none';
  renderVariants();
  draw();
  editorStatus(`${node.name}${node.enabled?'已启用':'已禁用'}，尚未保存`);
},true);

// Keep newly selected editor operations represented as separate nodes.
document.addEventListener('change',event=>{
  const select=event.target;
  if(select.id!=='filter'&&select.id!=='localCorrection')return;
  const type=select.id==='filter'?'filter':'local_correction';
  const value=select.value;
  const nodes=state.recipe.nodes||(state.recipe.nodes=[]);
  const node=nodes.find(item=>item.type===type);
  if(value==='none'){
    if(node)node.enabled=false;
  }else if(node){
    node.name=value;
    node.enabled=true;
  }else{
    nodes.push({id:type==='filter'?'filter':'local',type,name:value,enabled:true});
  }
  renderVariants();
},true);

function nodeDisplayName(node){
  if(node.type==='filter'||node.type==='local_correction'){
    const select=document.querySelector(node.type==='filter'?'#filter':'#localCorrection');
    const option=[...(select?.options||[])].find(item=>item.value===node.name);
    return option?.textContent?.trim()||node.name;
  }
  return node.name;
}
const __renderVariantsWithRawNames=renderVariants;
renderVariants=function(){
  __renderVariantsWithRawNames();
  $$('.recipe-node[data-node-index]').forEach(row=>{
    const node=state.recipe.nodes?.[Number(row.dataset.nodeIndex)];
    const label=row.querySelector('.node-grip')?.nextElementSibling;
    if(node&&label)label.textContent=nodeDisplayName(node);
  });
};

const curveIdentity=()=>[[0,0],[255,255]];
function ensureRecipeCurves(){
  state.recipe.curves??={};
  for(const channel of ['rgb','red','green','blue']){
    const points=state.recipe.curves[channel];
    state.recipe.curves[channel]=Array.isArray(points)&&points.length>=2?points.map(point=>[Number(point[0]),Number(point[1])]):curveIdentity();
  }
}
function curveValue(points,value){
  const sorted=[...points].sort((a,b)=>a[0]-b[0]);
  if(value<=sorted[0][0])return sorted[0][1];
  if(value>=sorted.at(-1)[0])return sorted.at(-1)[1];
  for(let i=1;i<sorted.length;i++)if(value<=sorted[i][0]){let left=sorted[i-1],right=sorted[i],ratio=(value-left[0])/Math.max(1,right[0]-left[0]);return left[1]+(right[1]-left[1])*ratio}
  return value;
}
function applyCurvesPreview(canvas){
  ensureRecipeCurves();
  if(state.recipe.nodes?.some(node=>node.type==='curves'&&node.enabled===false))return;
  const context=canvas.getContext('2d'),pixels=context.getImageData(0,0,canvas.width,canvas.height),data=pixels.data,curves=state.recipe.curves;
  for(let i=0;i<data.length;i+=4){let rgb=curveValue(curves.rgb,data[i]);data[i]=curveValue(curves.red,rgb);data[i+1]=curveValue(curves.green,curveValue(curves.rgb,data[i+1]));data[i+2]=curveValue(curves.blue,curveValue(curves.rgb,data[i+2]))}
  context.putImageData(pixels,0,0);
}
function curveNode(){
  ensureRecipeCurves();
  let node=state.recipe.nodes?.find(item=>item.type==='curves');
  if(!node){state.recipe.nodes??=[];node={id:'curves',type:'curves',name:'曲线',enabled:true};state.recipe.nodes.push(node)}
  node.enabled=true;
}
