  if(!state.nodeCompareMode||!left?.complete||!right?.complete)return;
  const original=$('#compareCanvas'),variant=$('#canvas');
  variant.width=right.naturalWidth;variant.height=right.naturalHeight;
  const context=variant.getContext('2d'),mid=Math.floor(variant.width/2);
  context.clearRect(0,0,variant.width,variant.height);
  context.save();context.beginPath();context.rect(0,0,mid,variant.height);context.clip();context.drawImage(left,0,0,variant.width,variant.height);context.restore();
  context.save();context.beginPath();context.rect(mid,0,variant.width-mid,variant.height);context.clip();context.drawImage(right,0,0,variant.width,variant.height);context.restore();
